function SearchableSelect({label,items,value,onChange,inputClass,onQuickAdd}){
 const selected=items.find(x=>String(x.id)===String(value));
 const [text,setText]=useState(selected?.name||'');
 const [open,setOpen]=useState(false);
 useEffect(()=>{setText(items.find(x=>String(x.id)===String(value))?.name||'')},[value,items]);
 const q=String(text||'').trim().toLocaleLowerCase();
 const matches=items.filter(x=>!q||String(x.name||'').toLocaleLowerCase().includes(q)).slice(0,30);
 return <div className="flex gap-1.5">
  <div className="relative flex-1">
   <input className={inputClass} value={text} placeholder={`${label} — ابحث بجزء من الاسم`} autoComplete="off"
    onFocus={()=>setOpen(true)}
    onChange={e=>{setText(e.target.value);onChange('');setOpen(true)}}
    onBlur={()=>setTimeout(()=>setOpen(false),120)}
    aria-label={label} aria-autocomplete="list" aria-expanded={open}/>
   {open&&<div className="absolute inset-x-0 top-full z-[80] mt-1 max-h-56 overflow-y-auto rounded-xl border border-border bg-card p-1 shadow-2xl">
    {matches.length?matches.map(x=><button key={x.id} type="button" onMouseDown={e=>e.preventDefault()} onClick={()=>{onChange(x.id);setText(x.name);setOpen(false)}} className={`block w-full rounded-lg px-3 py-2 text-right text-sm hover:bg-accent-soft hover:text-accent ${String(x.id)===String(value)?'bg-accent-soft font-black text-accent':''}`}>{x.name}</button>):<div className="px-3 py-3 text-center text-xs text-muted">لا توجد نتائج — <button type="button" onMouseDown={e=>e.preventDefault()} onClick={()=>{setOpen(false);onQuickAdd?.(text.trim())}} className="font-black text-accent underline">أضف الآن</button></div>}
   </div>}
  </div>
  {onQuickAdd&&<button type="button" title={`إضافة ${label} جديد`} onClick={()=>onQuickAdd('')} className="flex h-full min-h-[42px] w-10 shrink-0 items-center justify-center rounded-xl border border-accent-line bg-accent-soft text-accent hover:bg-accent hover:text-on-accent transition"><Plus size={18}/></button>}
 </div>
}

